messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Red vs Blue Race</title>
  <style>
    body { margin: 0; overflow: hidden; background: #87CEEB; }
    canvas { display: block; }
    .info {
      position: absolute;
      top: 20px;
      left: 20px;
      color: white;
      font-family: Arial, sans-serif;
      font-size: 18px;
      background: rgba(0,0,0,0.5);
      padding: 8px 16px;
      border-radius: 8px;
      pointer-events: none;
      z-index: 10;
    }
  </style>
</head>
<body>
  <div class="info">🏁 Red overtakes Blue — race resets</div>
  <script type="importmap">
    {
      "imports": {
        "three": "./three.module.js"
      }
    }
  </script>
  <script type="module">
    import * as THREE from 'three';

    // --- Setup scene, camera, renderer ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB); // sky blue

    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.set(0, 6, 14);
    camera.lookAt(0, 1, 5);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // --- Lights ---
    const ambient = new THREE.AmbientLight(0x404040, 1.2);
    scene.add(ambient);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
    dirLight.position.set(5, 10, 7);
    dirLight.castShadow = true;
    scene.add(dirLight);

    const backLight = new THREE.DirectionalLight(0xffffff, 0.5);
    backLight.position.set(-5, 5, -5);
    scene.add(backLight);

    // --- Ground ---
    const groundGeo = new THREE.PlaneGeometry(30, 30);
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x4a7a4a, roughness: 0.8 });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.1;
    ground.receiveShadow = true;
    scene.add(ground);

    // --- Track: two lanes with road markings ---
    const trackLength = 30;
    const laneWidth = 1.8;
    const trackMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.6 });
    const trackGeo = new THREE.BoxGeometry(trackLength, 0.1, laneWidth * 2 + 0.6);
    const track = new THREE.Mesh(trackGeo, trackMat);
    track.position.set(0, 0.05, 5);
    track.receiveShadow = true;
    scene.add(track);

    // Lane markings (white dashed lines)
    const lineMat = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0x222222 });
    const dashGeo = new THREE.BoxGeometry(0.4, 0.06, 0.1);
    for (let i = -2; i <= 2; i++) {
      const x = i * 1.8;
      for (let z = -5; z <= 15; z += 1.5) {
        const dash = new THREE.Mesh(dashGeo, lineMat);
        dash.position.set(x, 0.1, z);
        dash.castShadow = true;
        scene.add(dash);
      }
    }

    // Finish line (checkered pattern)
    const finishMatWhite = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0x111111 });
    const finishMatBlack = new THREE.MeshStandardMaterial({ color: 0x111111, emissive: 0x111111 });
    const squareSize = 0.4;
    const finishZ = 15;
    for (let i = -2; i < 2; i++) {
      for (let j = 0; j < 4; j++) {
        const x = i * 0.8 + (j % 2) * 0.4;
        const z = finishZ + (j % 2) * 0.2;
        const mat = (i + j) % 2 === 0 ? finishMatWhite : finishMatBlack;
        const sq = new THREE.Mesh(new THREE.BoxGeometry(squareSize, 0.08, squareSize), mat);
        sq.position.set(x, 0.1, finishZ);
        sq.castShadow = true;
        scene.add(sq);
      }
    }

    // Start line (white)
    const startMat = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0x222222 });
    const startLine = new THREE.Mesh(new THREE.BoxGeometry(4.0, 0.08, 0.3), startMat);
    startLine.position.set(0, 0.1, -2);
    scene.add(startLine);

    // --- Cars (large and visible) ---
    function createCar(color, isRed) {
      const carGroup = new THREE.Group();

      // Body
      const bodyGeo = new THREE.BoxGeometry(1.2, 0.6, 2.2);
      const bodyMat = new THREE.MeshStandardMaterial({ color: color, roughness: 0.3, metalness: 0.2 });
      const body = new THREE.Mesh(bodyGeo, bodyMat);
      body.position.y = 0.4;
      body.castShadow = true;
      carGroup.add(body);

      // Cabin (glass)
      const cabinGeo = new THREE.BoxGeometry(0.9, 0.5, 1.2);
      const cabinMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.1, metalness: 0.5 });
      const cabin = new THREE.Mesh(cabinGeo, cabinMat);
      cabin.position.set(0, 0.8, -0.2);
      cabin.castShadow = true;
      carGroup.add(cabin);

      // Wheels (4)
      const wheelGeo = new THREE.CylinderGeometry(0.3, 0.3, 0.3, 16);
      const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.9 });
      const wheelPositions = [
        [-0.7, 0.3, 0.8],
        [0.7, 0.3, 0.8],
        [-0.7, 0.3, -0.8],
        [0.7, 0.3, -0.8]
      ];
      wheelPositions.forEach(pos => {
        const wheel = new THREE.Mesh(wheelGeo, wheelMat);
        wheel.rotation.z = Math.PI / 2;
        wheel.position.set(pos[0], pos[1], pos[2]);
        wheel.castShadow = true;
        carGroup.add(wheel);
      });

      // Headlights
      const lightMat = new THREE.MeshStandardMaterial({ color: 0xffffaa, emissive: 0xffffaa });
      const headlightGeo = new THREE.SphereGeometry(0.15, 8, 8);
      const headlight1 = new THREE.Mesh(headlightGeo, lightMat);
      headlight1.position.set(-0.4, 0.4, 1.1);
      carGroup.add(headlight1);
      const headlight2 = new THREE.Mesh(headlightGeo, lightMat);
      headlight2.position.set(0.4, 0.4, 1.1);
      carGroup.add(headlight2);

      // Tail lights (red)
      const tailMat = new THREE.MeshStandardMaterial({ color: 0xff2222, emissive: 0xff2222 });
      const tailGeo = new THREE.SphereGeometry(0.12, 8, 8);
      const tail1 = new THREE.Mesh(tailGeo, tailMat);
      tail1.position.set(-0.4, 0.4, -1.1);
      carGroup.add(tail1);
      const tail2 = new THREE.Mesh(tailGeo, tailMat);
      tail2.position.set(0.4, 0.4, -1.1);
      carGroup.add(tail2);

      // Number decal (simple)
      const numMat = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0xffffff });
      const numGeo = new THREE.BoxGeometry(0.4, 0.3, 0.1);
      const num = new THREE.Mesh(numGeo, numMat);
      num.position.set(0, 0.5, 1.1);
      carGroup.add(num);

      return carGroup;
    }

    // Create red car (right lane) and blue car (left lane)
    const redCar = createCar(0xff0000, true);
    const blueCar = createCar(0x0044ff, false);

    // Position cars at start
    redCar.position.set(0.9, 0, -2);
    blueCar.position.set(-0.9, 0, -2);

    scene.add(redCar);
    scene.add(blueCar);

    // --- Race state ---
    const raceLength = 17; // from z=-2 to z=15
    let raceTime = 0;
    const raceDuration = 6; // seconds for full race (loop)

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);

      const dt = 1 / 60;
      raceTime += dt;

      // Cycle: 0 -> raceDuration, then reset
      const t = raceTime % raceDuration;
      const progress = t / raceDuration; // 0 to 1

      // Blue car: leads early, then slower
      const blueProgress = Math.min(progress * 1.25, 1); // blue reaches finish earlier but red overtakes
      // Red car: slower early, then accelerates
      const redProgress = Math.min(Math.max(progress * 1.6 - 0.25, 0), 1);

      // Map progress to Z position: start z=-2, finish z=15
      const startZ = -2;
      const endZ = 15;
      const blueZ = startZ + blueProgress * (endZ - startZ);
      const redZ = startZ + redProgress * (endZ - startZ);

      // Update car positions (x fixed: blue left, red right)
      blueCar.position.z = blueZ;
      redCar.position.z = redZ;

      // Slight bounce for visual interest
      blueCar.position.y = 0.1 * Math.sin(raceTime * 10);
      redCar.position.y = 0.1 * Math.sin(raceTime * 10 + 0.5);

      // Rotate wheels
      const wheelRotation = raceTime * 5;
      blueCar.children.forEach(child => {
        if (child.geometry && child.geometry.type === 'CylinderGeometry') {
          child.rotation.x = wheelRotation;
        }
      });
      redCar.children.forEach(child => {
        if (child.geometry && child.geometry.type === 'CylinderGeometry') {
          child.rotation.x = wheelRotation;
        }
      });

      // Camera: keep both cars in view, follow the action
      const midZ = (blueZ + redZ) / 2;
      const maxZ = Math.max(blueZ, redZ);
      // Camera moves slightly forward, but stays behind
      camera.position.z = 10 + maxZ * 0.35;
      camera.position.x = 0;
      camera.position.y = 6 + Math.sin(raceTime * 0.5) * 0.5;
      camera.lookAt(0, 1, midZ + 2);

      renderer.render(scene, camera);
    }

    animate();

    // Handle resize
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
</body>
</html>
```
